return {
	Name = "Gloomy Sleeper",
	Cost = 600,
	DandyStore = true,
	ApplySkin = function(p1) --[[ ApplySkin | Line: 7 ]]
		local CollectionService = game:GetService("CollectionService")

		p1:SetAttribute("PaintingTexture", "rbxassetid://73920383880337")

		for k, v in pairs(p1:GetDescendants()) do
			if v:IsA("MeshPart") and CollectionService:HasTag(v, "SkinPart") then
				if v.Material == Enum.Material.Neon then
					v.Color = Color3.fromRGB(100, 100, 120)

					continue
				end

				v.TextureID = "rbxassetid://134398763923866"

				continue
			end

			if v:IsA("ParticleEmitter") then
				v.Color = ColorSequence.new({ ColorSequenceKeypoint.new(0, Color3.fromRGB(150, 150, 170)), ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 200, 220)) })
			end
		end

		local Config = p1:WaitForChild("Config")
		local HurtTexture = Config:WaitForChild("HurtTexture")
		local BlinkTexture = Config:FindFirstChild("BlinkTexture")

		Config:FindFirstChild("NormalTexture").Texture = "rbxassetid://134398763923866"
		HurtTexture.Texture = "rbxassetid://85474521879426"

		if BlinkTexture then
			BlinkTexture.Texture = "rbxassetid://118249574491510"
		end

		local v1 = game.ServerStorage.SkinModelStorage[p1.Config.ModuleName.Value][script.Name][script.Name]:Clone()

		for k, v in pairs(v1:GetChildren()) do
			if v:IsA("MeshPart") then
				if v.Name == "Hat" then
					local Weld = Instance.new("Weld")

					v.Parent = p1:WaitForChild("Head")
					Weld.Parent = v
					Weld.Part0 = v
					Weld.Part1 = p1:WaitForChild("Head")
					v.Anchored = false

					continue
				end

				local v2 = p1:WaitForChild(v.Name)

				CollectionService:RemoveTag(v2, "SkinPart")

				local Weld = Instance.new("Weld")

				v.Parent = v2
				Weld.Parent = v
				Weld.Part0 = v
				Weld.Part1 = v2
				v.Anchored = false
				v2.Transparency = 1
			end
		end

		game:GetService("Debris"):AddItem(v1, 10)
	end
}